<template>
  <Card>
    <CardHeader>
      <CardTitle>Project Recruitment</CardTitle>
    </CardHeader>
    <CardContent>
      <NavigationGuard
        :saved-data="processedPassedData"
        :changed-data="processedDataFromForm"
        title="Warning"
        description="You have some unsaved changes on this tab! Save them before switching to another tab."
        confirm-text="Discard Changes"
      />
      <form id="settingsProjectRecruitmentForm" class="flex flex-col gap-6" @submit="onSubmit">
        <div class="flex items-center justify-between rounded-md border p-4">
          <div class="flex items-center gap-1">
            <label for="enabled" class="text-sm font-medium">Autonomous Project Recruitment</label>
            <Popover>
              <PopoverTrigger type="button"><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
              <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                <p class="font-semibold mb-4">Autonomous Project Recruitment</p>
                {{ settingsFieldDescriptions.project_recruitment.enabled }}
              </PopoverContent>
            </Popover>
          </div>
          <Switch id="enabled" :model-value="values.enabled" @update:model-value="(v) => setFieldValue('enabled', v)" />
        </div>

        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Max Cross-Promos"
              name="max_cross_promos"
              :is-required="true"
              :description="settingsFieldDescriptions.project_recruitment.max_cross_promos"
            >
              <template #default="{ slots }">
                <Input id="max_cross_promos" type="number" min="0" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Cross-Promo Max Distance (miles)"
              name="cross_promo_max_distance_miles"
              :is-required="true"
              :description="settingsFieldDescriptions.project_recruitment.cross_promo_max_distance_miles"
            >
              <template #default="{ slots }">
                <Input id="cross_promo_max_distance_miles" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>

          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Cross-Promo Recent Mention Window (days)"
              name="cross_promo_recent_mention_window_days"
              :is-required="true"
              :description="settingsFieldDescriptions.project_recruitment.cross_promo_recent_mention_window_days"
            >
              <template #default="{ slots }">
                <Input
                  id="cross_promo_recent_mention_window_days"
                  type="number"
                  min="1"
                  v-bind="slots.componentField"
                />
              </template>
            </FormItemWrapper>
          </div>
        </div>

        <div class="flex justify-end">
          <Button
            type="submit"
            :loading="isUpdateSettingsProjectRecruitmentLoading"
            :disabled="isEqual(processedDataFromForm, processedPassedData) || isUpdateSettingsProjectRecruitmentLoading"
          >
            Save Project Recruitment Settings
          </Button>
        </div>
      </form>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import type { GetAllSystemSettingsResponse, ProjectRecruitmentConfig } from '~/client';
import { formSchema } from '~/constants/validationSchemas/recruitmentSettingsProjectRecruitment';
import { useUpdateSettingsProjectRecruitment } from '~/mutations/system/updateSettingsProjectRecruitment';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';

const props = defineProps<{
  settings: GetAllSystemSettingsResponse;
}>();

definePageMeta({
  roles: ['admin'],
});

const { updateSettingsProjectRecruitment, isUpdateSettingsProjectRecruitmentLoading } =
  useUpdateSettingsProjectRecruitment();

const { handleSubmit, values, resetForm, setFieldValue } = useForm({
  validationSchema: formSchema,
  initialValues: {
    enabled: false,
    max_cross_promos: undefined,
    cross_promo_max_distance_miles: undefined,
    cross_promo_recent_mention_window_days: undefined,
  },
});

function hydrate(config: ProjectRecruitmentConfig) {
  resetForm({
    values: {
      enabled: config.enabled,
      max_cross_promos: config.max_cross_promos,
      cross_promo_max_distance_miles: config.cross_promo_max_distance_miles,
      cross_promo_recent_mention_window_days: config.cross_promo_recent_mention_window_days,
    },
  });
}

onMounted(() => hydrate(props.settings.project_recruitment));

const processedPassedData = computed(() => props.settings.project_recruitment);

const processedDataFromForm = computed<ProjectRecruitmentConfig>(() => ({
  enabled: values.enabled ?? false,
  max_cross_promos: toNumberOrNull(values.max_cross_promos) ?? 0,
  cross_promo_max_distance_miles: toNumberOrNull(values.cross_promo_max_distance_miles) ?? 0,
  cross_promo_recent_mention_window_days: toNumberOrNull(values.cross_promo_recent_mention_window_days) ?? 0,
}));

const onSubmit = handleSubmit(async (formValues) => {
  await updateSettingsProjectRecruitment(formValues as ProjectRecruitmentConfig);
  hydrate(formValues as ProjectRecruitmentConfig);
});
</script>
