import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { nonNegativeIntPreset, positiveIntPreset } from './utils';

export const schemaObject = {
  enabled: z.boolean({ message: 'Enabled flag is required' }),
  max_cross_promos: nonNegativeIntPreset({
    max: 10,
    requiredMessage: 'Max cross-promos is required',
    maxMessage: 'Must be at most 10',
    integerMessage: 'Must be a whole number',
  }),
  cross_promo_max_distance_miles: positiveIntPreset({
    max: 5000,
    requiredMessage: 'Max distance is required',
    maxMessage: 'Must be at most 5000',
    integerMessage: 'Must be a whole number',
  }),
  cross_promo_recent_mention_window_days: positiveIntPreset({
    max: 365,
    requiredMessage: 'Recent mention window is required',
    maxMessage: 'Must be at most 365',
    integerMessage: 'Must be a whole number',
  }),
};

export const formSchema = toTypedSchema(z.object(schemaObject));
