import { updateProjectRecruitmentSettings, type ProjectRecruitmentConfig } from '~/client';

export const useUpdateSettingsProjectRecruitment = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: ProjectRecruitmentConfig): Promise<ProjectRecruitmentConfig> =>
      updateProjectRecruitmentSettings({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      showToastSuccess('Project recruitment settings updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateSettingsProjectRecruitment: mutateAsync,
    isUpdateSettingsProjectRecruitmentLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
